/**
 * Display and parsing safeguards for public Devfolio organizer content.
 * No inferred prizes, no fabricated event summaries, and no scraping beyond
 * the same vetted public microsite payload already used for source evidence.
 */

/** Matches only HackerMate's historical autogenerated provider sentence. */
export function isGeneratedProviderDescription(value: unknown): boolean {
  return typeof value === "string" &&
    /^.{1,260}\. (?:Online event\. |In-person event\. |Hybrid event\. )?See the official event page for the complete rules, eligibility and current registration information\.$/i.test(value.trim());
}

export function isUnverifiedZeroPrize(value: unknown): boolean {
  return typeof value === "string" && /^(?:(?:USD|INR|[$₹])\s*)?0+(?:[.,]0+)?$/i.test(value.trim());
}

function organizerText(value: unknown): string {
  if (typeof value !== "string") return "";
  // Organizer Markdown/HTML is plain display text, never executable markup.
  return value.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/&(?:nbsp|amp|lt|gt|quot|#39);/gi, entity => ({
      "&nbsp;": " ", "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&#39;": "'",
    }[entity.toLowerCase()] || " "))
    .replace(/[\u200b-\u200d\ufeff]/gi, "")
    .replace(/\s+/g, " ").trim();
}

/** Only explicit, human-authored public microsite fields; never generate prose from dates/status. */
export function devfolioOrganizerDescription(hackathon: Record<string, unknown>): string {
  const about = [
    hackathon.about, hackathon.description, hackathon.about_description,
    hackathon.overview,
  ].map(organizerText).find(v => v.length >= 70 && !isGeneratedProviderDescription(v));
  if (about) return about.slice(0, 1500).trim();
  const tagline = organizerText(hackathon.tagline);
  return tagline.length >= 30 && !isGeneratedProviderDescription(tagline) ? tagline.slice(0, 300) : "";
}

/** Aggregate zero is not proof the organizer promises a zero-prize event. */
export function devfolioAdvertisedPrize(value: unknown, currency: unknown): { prize_pool: string | null; currency: string | null } {
  const input = typeof value === "number" ? String(value) : typeof value === "string" ? value.trim() : "";
  const numeric = /^(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{1,2})?$/.test(input) ? Number(input.replace(/,/g, "")) : NaN;
  if (!Number.isFinite(numeric) || numeric <= 0 || numeric > Number.MAX_SAFE_INTEGER)
    return { prize_pool: null, currency: null };
  return { prize_pool: String(numeric), currency: typeof currency === "string" && /^(?:USD|INR)$/i.test(currency.trim()) ? currency.trim().toUpperCase() : null };
}
